\label{S:T2}
The proof essentially follows the arguments in the previous section, the main difference relying in the fact that for $\mathcal S>0$ we have that \eqref{eq:systemlinearized}  is a system of mixed orders. Thereby the energy estimates require some additional investigation. The existence of local solutions of the approximated Galerkin systems are straightforward due to Picard--Lindel\"of's theorem (see Subsection \ref{ss:gl}). The energy estimates then ensure that the approximated solutions exist globally. Furthermore, the energy estimates provide the necessary a priori bounds to pass to the limit in the Galerkin approximation; thereby guaranteeing the existence of a global weak solution in the sense of Definition \ref{defi1}. In view of the weak lower semicontinuity of the norm, the global weak solution inherits the energy estimates for the approximated solutions and we can conclude the regularity and exponential decay of the solution.

If $(h_0,\Gamma_0)$ are nonnegative bounded initial data, we set 
 $$
 h_\sharp=\frac{1}{2\pi}\int_{\mathbb T} h_0(x)dx\quad\mbox{and}\quad \Gamma_\sharp=\frac{1}{2\pi}\int_{\mathbb T} \Gamma_0(x)dx.
 $$
 The constants $h_\sharp$ and $\Gamma_\sharp$ represent the mean of the initial data and they are a steady state of the system \eqref{eq:systemA}. In our studies we consider the evolution of the distance of a solution $(h,\Gamma)$ to the steady state $(h_\sharp,\Gamma_\sharp)$. For this purpose, we define new unknowns
\begin{equation}\label{newunknown}
f=h-h_\sharp,\quad \Theta=\Gamma-\Gamma_\sharp,
\end{equation}
which have zero mean. 
In the new variables \eqref{newunknown}, the system \eqref{eq:systemA} can be rewritten as
\begin{subequations}\label{eq:systemlinearized}
\begin{alignat}{2}
\partial_t f-\frac{h_\sharp^2}{2}\partial_x^2 \Theta +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)\partial_x^2 f+\frac{\mathcal{S}}{3}h_\sharp^3\partial_x^4 f&=\sum_{j=1}^4 N_j,\; &&\mbox{in}\quad (0,T)\times {\mathbb T}\\
\partial_t \Theta -\left(h_\sharp\Gamma_\sharp+\mathcal{D}\right)\partial_x^2\Theta+\left(\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\frac{\mathcal{G}}{2}\bGh_\sharp^2\right) \partial_x^2f+\frac{\mathcal{S}}{2}\bGh_\sharp^2 \partial_x^4f &= \sum_{j=5}^8 N_j,\;&& \mbox{in}\quad (0,T)\times {\mathbb T}
\end{alignat}
\end{subequations}
with initial conditions
\[
f(0,x)=f_0(x)\quad \mbox{and}\quad \Theta(0,x)=\Theta_0(x)\qquad \mbox{for all} \quad x\in \Omega,
\]
where $f_0(x)=h_0(x)-h_\sharp$ and $\Theta_0(x)=\Gamma_0(x)-\Gamma_\sharp$ are the initial displacement functions from the flat states $h_\sharp$ and $\Gamma_\sharp$, respectively.
The nonlinear terms $N_i$, $i=1,\dots,8,$ on the right hand side of \eqref{eq:systemlinearized} are defined as
\begin{align*}
N_1&=\partial_x\left[\left(\frac{f^2}{2}+fh_\sharp\right)\partial_x \Theta\right],\\
N_2&=\partial_x \left[\frac{\mathcal{G}}{3}\left(3h_\sharp^2 f+3f^2h_\sharp+f^3\right)\partial_x f\right],\\
N_3&=-\partial_x \left[\frac{\mathcal{S}}{3}\left(3h_\sharp^2 f+3f^2h_\sharp+f^3\right)\partial_x^3 f\right],\\
N_4&=\partial_x \left[\mathcal{A}\frac{f}{h_\sharp^2(1+\frac{f}{h_\sharp})}\partial_x f \right],\\
N_5&=\partial_x\left[\left(\Gamma_\sharp f+\Thetah_\sharp+\Theta f\right)\partial_x \Theta\right],\\
N_6&=\partial_x\left[\frac{\mathcal{G}}{2}\left(\Gamma_\sharp f^2+2\bGh_\sharp f+\Thetah_\sharp^2+\Theta f^2+2\Thetah_\sharp f\right)\partial_x f\right],\\
N_7&=-\partial_x\left[\frac{\mathcal{S}}{2}\left(\Gamma_\sharp f^2+2\bGh_\sharp f+\Thetah_\sharp^2+\Theta f^2+2\Thetah_\sharp f\right)\partial_x^3 f\right],\\
N_8&=\partial_x \left[\Theta \frac{3\mathcal{A}}{2h_\sharp^2} \frac{(f^2+2h_\sharp f)\partial_x f }{(h_\sharp+f)^{2}}+\Gamma_\sharp\frac{3\mathcal{A}}{2h_\sharp^2} \frac{(f^2+2h_\sharp f)\partial_x f }{(h_\sharp+f)^{2}}-\Theta \frac{3\mathcal{A}}{2h_\sharp^2} \partial_x f \right]\\
&= \partial_x \left[ \frac{3\mathcal{A}}{2}\frac{2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2}{h_\sharp^2(f+h_\sharp)^2}\partial_x f\right].
\end{align*}

Note that, for $|r|<1$, we have
\begin{align}
\frac{1}{1+r}&=\sum_{j=1}^\infty (-1)^{j+1}r^{j-1},\label{eq:taylor1} \\
\frac{1}{\left(1+r\right)^2}&=\sum_{j=1}^\infty j(-1)^{j+1}r^{j-1},\label{eq:taylor2}\\
\frac{1}{\left(1+r\right)^3}&=\frac{1}{2}\sum_{j=2}^\infty j(j-1)(-1)^{j}r^{j-2}.\label{eq:taylor3}
\end{align}
Consequently, under the assumption that
\begin{equation}\label{restriction1}
\|f\|_{L^\infty}\leq \|f\|_{\dot A^0}< h_\sharp,
\end{equation}
