\begin{align}
N_4&=\mathcal{A} \bigg{[}\left(\frac{f}{h_\sharp^2}\partial_x^2 f +\left(\frac{\partial_x f}{h_\sharp}\right)^2\right)\sum_{j=1}^\infty (-1)^{j+1}\left(\frac{f}{h_\sharp}\right)^{j-1}-\frac{f}{h_\sharp^3}(\partial_x f)^2\sum_{j=1}^\infty j(-1)^{j+1}\left(\frac{f}{h_\sharp}\right)^{j-1} \bigg{]}.\label{NL4}
\end{align}
Similarly, invoking  \eqref{eq:taylor2} and \eqref{eq:taylor3} we have that
\begin{align}
N_8&=\partial_x \left[ \frac{3\mathcal{A}}{2}\frac{2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2}{h_\sharp^2(f+h_\sharp)^2}\partial_x f\right]\nonumber\\
&= \frac{3\mathcal{A}}{2h_\sharp^4}\left[\frac{2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2}{\left(\frac{f}{h_\sharp}+1\right)^2}\partial_x^2 f+\frac{2\partial_x f\bGh_\sharp+2f\partial_x f\Gamma_\sharp-\partial_x \Theta h_\sharp^2}{\left(\frac{f}{h_\sharp}+1\right)^2}\partial_x f\right]\nonumber\\
&\quad- \frac{3\mathcal{A}}{h_\sharp^4}\left[\frac{2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2}{\left(\frac{f}{h_\sharp}+1\right)^3}\frac{(\partial_x f)^2}{h_\sharp}\right]\nonumber\\
&=\frac{3\mathcal{A}}{2h_\sharp^4}\left[\left(2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2\right)\partial_x^2 f+\left(2\partial_x f\bGh_\sharp+2f\partial_x f\Gamma_\sharp-\partial_x \Theta h_\sharp^2\right)\partial_x f\right]\sum_{j=1}^\infty j(-1)^{j+1}\left(\frac{f}{h_\sharp}\right)^{j-1}\nonumber\\
&\quad- \frac{3\mathcal{A}}{h_\sharp^4}\left[\left(2f\bGh_\sharp+f^2\Gamma_\sharp-\Theta h_\sharp^2\right)\frac{(\partial_x f)^2}{h_\sharp}\right]\frac{1}{2}\sum_{j=2}^\infty j(j-1)(-1)^{j}\left(\frac{f}{h_\sharp}\right)^{j-2}.\label{NL8}
\end{align}



\medskip
We fix the initial data $h_0$, $\Gamma_0$ for problem \eqref{eq:systemA}. Thereby, the constants $h_\sharp$ and $\Gamma_\sharp$ are uniquely determined and we are going to state our results in terms of  $f$,$\Theta$ for \eqref{eq:systemlinearized}.

